var e={languageName:`العربية`,nav:{home:`الرئيسية`,privacyPolicy:`سياسة الخصوصية`,termsOfService:`شروط الخدمة`,cookiePolicy:`سياسة ملفات تعريف الارتباط`,dataCollection:`جمع البيانات`,permissionsPolicy:`سياسة الأذونات`,refundPolicy:`سياسة الاسترجاع`,disclaimerPolicy:`إخلاء المسؤولية`,accessibilityPolicy:`سياسة إمكانية الوصول`,childSafetyPolicy:`سياسة سلامة الأطفال`,selectLanguage:`اختر اللغة`},common:{lastUpdated:`آخر تحديث`,effectiveDate:`تاريخ السريان`,contactUs:`اتصل بنا`,email:`البريد الإلكتروني`,backToHome:`العودة إلى الرئيسية`,tableOfContents:`جدول المحتويات`},privacy:{title:`سياسة الخصوصية`,intro:`نحن نقدر خصوصيتك ونلتزم بحماية معلوماتك الشخصية. توضح هذه السياسة كيف نقوم بجمع واستخدام ومشاركة معلوماتك عند استخدامك لخدماتنا.`,sections:{informationWeCollect:{title:`المعلومات التي نجمعها`,personal:`قد نجمع معلومات شخصية مثل اسمك وعنوان بريدك الإلكتروني ومعلومات الاتصال الأخرى عند التسجيل.`,usage:`نجمع معلومات حول كيفية تفاعلك مع خدماتنا، بما في ذلك الصفحات التي تزورها والروابط التي تنقر عليها.`,device:`قد نقوم بجمع معلومات حول الجهاز الذي تستخدمه للوصول إلى خدماتنا، مثل عنوان IP ونوع المتصفح.`},howWeUse:{title:`كيف نستخدم معلوماتك`,content:`نستخدم معلوماتك لتقديم خدماتنا وتحسينها وتخصيصها. كما نستخدمها للتواصل معك بشأن التحديثات والعروض ولأغراض الأمان.`},dataSharing:{title:`مشاركة البيانات`,content:`لا نقوم ببيع معلوماتك الشخصية لأطراف ثالثة. قد نشارك بياناتك مع مقدمي خدمات موثوقين يساعدوننا في تشغيل خدماتنا، وذلك بموجب اتفاقيات سرية صارمة.`},dataSecurity:{title:`أمن البيانات`,content:`ننفذ تدابير أمنية تقنية وتنظيمية معقولة لحماية معلوماتك الشخصية من الوصول غير المصرح به أو التغيير أو الكشف أو التدمير.`},yourRights:{title:`حقوقك`,content:`لديك الحق في الوصول إلى معلوماتك الشخصية وتصحيحها وحذفها. يمكنك أيضاً الاعتراض على معالجة معينة لبياناتك أو طلب تقييدها.`},retention:{title:`الاحتفاظ بالبيانات`,content:`نحتفظ بمعلوماتك الشخصية فقط طالما كان ذلك ضرورياً للأغراض الموضحة في هذه السياسة، أو كما يقتضيه القانون.`},thirdPartyLinks:{title:`روابط الجهات الخارجية`,content:`قد تحتوي خدماتنا على روابط لمواقع إلكترونية تابعة لجهات خارجية. نحن لسنا مسؤولين عن ممارسات الخصوصية أو محتوى تلك المواقع.`},changes:{title:`تغييرات على هذه السياسة`,content:`قد نقوم بتحديث هذه السياسة من وقت لآخر. سنقوم بإعلامك بأي تغييرات جوهرية عن طريق نشر السياسة المحدثة على موقعنا.`}}},terms:{title:`شروط الخدمة`,intro:`يرجى قراءة شروط الخدمة هذه بعناية قبل استخدام خدماتنا. باستخدامك لخدماتنا، فإنك توافق على الالتزام بهذه الشروط.`,sections:{acceptance:{title:`قبول الشروط`,content:`من خلال الوصول إلى خدماتنا أو استخدامها، فإنك توافق على الالتزام بهذه الشروط وجميع القوانين واللوائح المعمول بها. إذا كنت لا توافق على هذه الشروط، يرجى عدم استخدام خدماتنا.`},useOfService:{title:`استخدام الخدمة`,content:`يجب عليك استخدام خدماتنا فقط للأغراض المشروعة وبطريقة لا تنتهك حقوق الآخرين أو تقيد استخدامهم للخدمة.`},userAccounts:{title:`حسابات المستخدمين`,content:`أنت مسؤول عن الحفاظ على سرية معلومات حسابك وكلمة المرور. يجب عليك إبلاغنا على الفور بأي استخدام غير مصرح به لحسابك.`},intellectualProperty:{title:`الملكية الفكرية`,content:`جميع المحتويات والمواد المتوفرة على خدماتنا هي ملك لنا أو لمرخصينا ومحمية بموجب قوانين حقوق النشر والعلامات التجارية وغيرها من حقوق الملكية الفكرية.`},prohibitedActivities:{title:`الأنشطة المحظورة`,content:`يُحظر عليك استخدام خدماتنا لأي غرض غير قانوني أو لنقل أي فيروسات أو شفرات خبيثة أو للتدخل في أمان أو وظائف الخدمة.`},limitation:{title:`حدود المسؤولية`,content:`إلى أقصى حد يسمح به القانون، لن نكون مسؤولين عن أي أضرار غير مباشرة أو عرضية أو تبعية ناشئة عن استخدامك لخدماتنا.`},termination:{title:`الإنهاء`,content:`نحتفظ بالحق في إنهاء أو تعليق وصولك إلى خدماتنا في أي وقت ولأي سبب، بما في ذلك انتهاكك لهذه الشروط.`},governingLaw:{title:`القانون الحاكم`,content:`تخضع هذه الشروط وتفسر وفقاً لقوانين الولاية القضائية التي نعمل فيها، دون مراعاة لتعارض أحكام القوانين.`}}},cookies:{title:`سياسة ملفات تعريف الارتباط`,intro:`توضح هذه السياسة كيف نستخدم ملفات تعريف الارتباط والتقنيات المشابهة لتقديم وتخصيص وتقييم خدماتنا وتحسينها وتوفير الأمان.`,sections:{whatAreCookies:{title:`ما هي ملفات تعريف الارتباط؟`,content:`ملفات تعريف الارتباط هي ملفات نصية صغيرة يتم تخزينها على جهازك عند زيارة موقع ويب. تساعد هذه الملفات الموقع على تذكر أفعالك وتفضيلاتك على مدار فترة زمنية.`},typesOfCookies:{title:`أنواع ملفات تعريف الارتباط التي نستخدمها`,essential:`هذه الملفات ضرورية لعمل الموقع بشكل صحيح ولا يمكن إيقاف تشغيلها في أنظمتنا.`,performance:`تسمح لنا هذه الملفات بحساب الزيارات ومصادر الزيارات حتى نتمكن من قياس وتحسين أداء موقعنا.`,functional:`تمكّن هذه الملفات الموقع من توفير وظائف وتخصيصات محسنة.`,advertising:`قد يتم تعيين هذه الملفات من خلال موقعنا بواسطة شركائنا في مجال الإعلانات لبناء ملف تعريف لاهتماماتك.`},managingCookies:{title:`إدارة ملفات تعريف الارتباط`,content:`يمكنك التحكم في ملفات تعريف الارتباط وإدارتها من خلال إعدادات المتصفح الخاص بك. يرجى ملاحظة أن تعطيل بعض ملفات تعريف الارتباط قد يؤثر على وظائف موقعنا.`},thirdPartyCookies:{title:`ملفات تعريف ارتباط الجهات الخارجية`,content:`قد نستخدم خدمات من جهات خارجية تستخدم أيضاً ملفات تعريف الارتباط الخاصة بها. تخضع هذه الملفات لسياسات الخصوصية الخاصة بتلك الجهات.`}}},dataCollection:{title:`سياسة جمع البيانات`,intro:`توضح هذه السياسة بالتفصيل البيانات التي نجمعها منك وكيفية جمعها واستخدامها والأساس القانوني لذلك.`,sections:{whatWeCollect:{title:`البيانات التي نجمعها`,content:`نقوم بجمع المعلومات الشخصية مثل الاسم والبريد الإلكتروني، وبيانات الاستخدام، والمعلومات الفنية حول جهازك واتصالك بالإنترنت.`},howWeCollect:{title:`كيف نجمع البيانات`,content:`نجمع البيانات مباشرة منك عندما تقدمها لنا، وتلقائياً أثناء تنقلك عبر الموقع باستخدام ملفات تعريف الارتباط وتقنيات التتبع.`},purpose:{title:`الغرض من جمع البيانات`,content:`الغرض الأساسي من جمع البيانات هو تقديم خدماتنا وتحسينها، وتخصيص تجربتك، والتواصل معك، وضمان أمان منصتنا.`},legalBasis:{title:`الأساس القانوني`,content:`نعتمد على أسس قانونية مختلفة لمعالجة بياناتك، بما في ذلك موافقتك، وتنفيذ العقد، والامتثال للالتزامات القانونية، ومصالحنا المشروعة.`},storage:{title:`تخزين البيانات`,content:`يتم تخزين بياناتك بشكل آمن على خوادمنا ومزودي الخدمات السحابية الموثوق بهم، مع تنفيذ تدابير التشفير والوصول الصارمة.`},userControl:{title:`تحكم المستخدم`,content:`لديك سيطرة كاملة على بياناتك. يمكنك الوصول إلى معلوماتك الشخصية أو تحديثها أو تصديرها أو حذفها من خلال إعدادات حسابك.`}}},permissions:{title:`سياسة الأذونات`,intro:`لتقديم أفضل تجربة ممكنة، قد يطلب تطبيقنا الوصول إلى ميزات معينة على جهازك. توضح هذه السياسة الأذونات التي نطلبها ولماذا.`,sections:{camera:{title:`الكاميرا`,why:`نطلب الوصول إلى الكاميرا للسماح لك بالتقاط الصور أو مقاطع الفيديو ومشاركتها مباشرة داخل التطبيق.`,howToManage:`يمكنك إبطال إذن الكاميرا في أي وقت من خلال إعدادات جهازك.`},microphone:{title:`الميكروفون`,why:`يعد الوصول إلى الميكروفون ضرورياً لتمكين الميزات الصوتية وتسجيل مقاطع الفيديو بصوت.`,howToManage:`إدارة أذونات الميكروفون الخاصة بك عبر إعدادات خصوصية الجهاز.`},location:{title:`الموقع`,why:`نستخدم بيانات موقعك لتقديم محتوى وخدمات تعتمد على الموقع، مثل العثور على أماكن قريبة.`,howToManage:`يمكنك اختيار مشاركة موقعك دائماً، أو أثناء استخدام التطبيق فقط، أو عدم مشاركته مطلقاً من خلال إعدادات الموقع.`},notifications:{title:`الإشعارات`,why:`نرسل إشعارات لإبقائك على اطلاع بالتحديثات والرسائل والتنبيهات المهمة المتعلقة بحسابك.`,howToManage:`تحكم في تفضيلات الإشعارات من إعدادات الإشعارات بجهازك أو داخل التطبيق.`},storage:{title:`التخزين`,why:`نحتاج إلى الوصول إلى مساحة التخزين لحفظ الملفات وتخزين البيانات مؤقتاً لتحسين الأداء وتحميل الصور.`,howToManage:`يمكن ضبط أذونات التخزين في إعدادات إدارة التطبيقات بجهازك.`},contacts:{title:`جهات الاتصال`,why:`نطلب الوصول إلى جهات الاتصال الخاصة بك لمساعدتك في العثور على أصدقاء والتواصل معهم على منصتنا.`,howToManage:`يمكنك تعطيل الوصول إلى جهات الاتصال من خلال إعدادات الخصوصية لجهازك.`},biometric:{title:`المقاييس الحيوية`,why:`تُستخدم المصادقة البيومترية (مثل بصمة الإصبع أو التعرف على الوجه) لتسجيل الدخول الآمن والسريع.`,howToManage:`يمكن تمكين أو تعطيل المصادقة البيومترية ضمن إعدادات أمان التطبيق.`},dataNotStored:`نحن لا نقوم بتخزين بياناتك البيومترية على خوادمنا؛ تتم معالجتها محلياً على جهازك.`}},refund:{title:`سياسة الاسترجاع`,intro:`نحن نسعى جاهدين لضمان رضاك عن منتجاتنا وخدماتنا. تحدد هذه السياسة الشروط والأحكام المتعلقة بعمليات الاسترداد والإلغاء.`,sections:{eligibility:{title:`الأهلية للاسترداد`,content:`أنت مؤهل لاسترداد الأموال إذا طلبت ذلك خلال 14 يوماً من الشراء ولم يتم استخدام الخدمة أو المنتج بشكل مكثف. قد تنطبق شروط محددة حسب نوع المنتج.`},process:{title:`عملية الاسترداد`,content:`لبدء عملية الاسترداد، يرجى الاتصال بفريق دعم العملاء مع تقديم رقم الطلب وسبب طلب الاسترداد. ستتم مراجعة طلبك خلال 3 أيام عمل.`},nonRefundable:{title:`العناصر غير القابلة للاسترداد`,content:`الخدمات التي تم تقديمها بالكامل، والمنتجات الرقمية القابلة للتنزيل بعد الوصول إليها، والاشتراكات بعد فترة الإصدار التجريبي المجاني غير قابلة للاسترداد.`},timeline:{title:`الجدول الزمني للاسترداد`,content:`بمجرد الموافقة على طلبك، سيتم معالجة الاسترداد وإضافة الرصيد تلقائياً إلى بطاقتك الائتمانية أو طريقة الدفع الأصلية، في غضون 7-10 أيام عمل.`}}},disclaimer:{title:`إخلاء المسؤولية`,intro:`المعلومات المقدمة على منصتنا هي لأغراض إعلامية عامة فقط. يرجى قراءة إخلاء المسؤولية هذا لفهم حدود مسؤوليتنا.`,sections:{generalDisclaimer:{title:`إخلاء المسؤولية العام`,content:`نحن نقدم المعلومات كما هي دون أي ضمانات من أي نوع، صريحة أو ضمنية. لا نتحمل المسؤولية عن أي أخطاء أو سهو في المحتوى.`},professionalAdvice:{title:`لا توجد استشارة مهنية`,content:`لا تشكل المعلومات الواردة في هذا الموقع استشارة مهنية قانونية أو مالية أو طبية. يجب عليك استشارة محترف مؤهل قبل اتخاذ أي قرارات بناءً على المعلومات المقدمة.`},externalLinks:{title:`الروابط الخارجية`,content:`قد يحتوي موقعنا على روابط لمواقع خارجية. نحن لا نؤيد أو نتحمل المسؤولية عن محتوى أو دقة أو ممارسات هذه المواقع الخارجية.`},accuracy:{title:`دقة المعلومات`,content:`بينما نسعى للحفاظ على المعلومات محدثة وصحيحة، فإننا لا نقدم أي تعهدات أو ضمانات من أي نوع بشأن اكتمال أو دقة أو موثوقية المعلومات.`}}},accessibility:{title:`سياسة إمكانية الوصول`,intro:`نحن ملتزمون بجعل موقعنا وخدماتنا في متناول الجميع، بما في ذلك الأشخاص ذوي الإعاقة. نحن نسعى جاهدين لتوفير تجربة شاملة لجميع المستخدمين.`,sections:{commitment:{title:`التزامنا`,content:`نحن نؤمن بأن الإنترنت يجب أن يكون متاحاً ومتاحاً للجميع. نحن نعمل باستمرار على تحسين إمكانية الوصول وتجربة المستخدم للجميع.`},standards:{title:`معايير إمكانية الوصول`,content:`يهدف موقعنا إلى التوافق مع إرشادات إمكانية الوصول إلى محتوى الويب (WCAG) 2.1 المستوى AA لضمان سهولة الوصول إلى المحتوى.`},features:{title:`ميزات إمكانية الوصول`,content:`يتضمن موقعنا ميزات مثل التنقل عبر لوحة المفاتيح، والنص البديل للصور، وتباين الألوان المناسب، ودعم قارئات الشاشة لتسهيل الاستخدام.`},feedback:{title:`التعليقات والمساعدة`,content:`إذا واجهت أي صعوبة في الوصول إلى أي جزء من موقعنا، يرجى الاتصال بنا. نحن نرحب بملاحظاتك ويسعدنا تقديم المساعدة المطلوبة.`}}},childSafety:{title:`سياسة سلامة الأطفال`,intro:`حماية خصوصية وسلامة الأطفال على الإنترنت هي أولوية قصوى بالنسبة لنا. تشرح هذه السياسة كيف نتعامل مع المعلومات المتعلقة بالقصر.`,sections:{ageRequirement:{title:`متطلبات العمر`,content:`خدماتنا غير موجهة للأطفال دون سن 13 عاماً. يجب أن يكون عمرك 13 عاماً على الأقل لإنشاء حساب أو استخدام خدماتنا.`},parentalConsent:{title:`موافقة الوالدين`,content:`للمستخدمين الذين تتراوح أعمارهم بين 13 و 18 عاماً، نطلب موافقة الوالدين أو الوصي القانوني لجمع واستخدام المعلومات الشخصية.`},dataHandling:{title:`التعامل مع البيانات`,content:`إذا علمنا أننا جمعنا معلومات شخصية من طفل دون سن 13 عاماً دون التحقق من موافقة الوالدين، فسنتخذ خطوات لحذف هذه المعلومات من خوادمنا فوراً.`},reporting:{title:`الإبلاغ عن مخاوف`,content:`إذا كنت والداً أو وصياً وتعتقد أن طفلك قد زودنا بمعلومات شخصية، يرجى الاتصال بنا على الفور وسنقوم باتخاذ الإجراءات اللازمة لحماية خصوصيته.`}}}};export{e as default};